import type {CrmCompany,CrmContact,CrmLead,CrmFollowUp,CrmMember,LeadStage} from '../../src/crm/contracts.ts';
export interface CrmLeadFilter {query?:string;country?:string;stage?:LeadStage|'';owner?:string;ownerMemberId?:string|null;source?:string;tag?:string|string[];createdFrom?:string;createdTo?:string;nextFollowUpFrom?:string;nextFollowUpTo?:string;verificationStatus?:string;due?:boolean;overdue?:boolean;archived?:boolean;includeArchived?:boolean}
export interface CrmRow {lead:CrmLead;company?:CrmCompany;contacts:CrmContact[];followup?:CrmFollowUp;owner:string;isDue:boolean}
export interface CrmQueryData {companies:CrmCompany[];contacts:CrmContact[];leads:CrmLead[];followups:CrmFollowUp[];members?:CrmMember[]}
function boundary(value:string|undefined,end=false):number|undefined {if(!value)return undefined;if(!/^\d{4}-\d{2}-\d{2}$/.test(value))throw Error('Invalid CRM date');const n=Date.parse(value+'T00:00:00.000+08:00');if(!Number.isFinite(n)||new Date(n+8*3600000).toISOString().slice(0,10)!==value)throw Error('Invalid CRM date');return n+(end?86400000-1:0);}
export function projectCrmRows(data:CrmQueryData,filter:CrmLeadFilter={},now:number):CrmRow[]{
 const from=boundary(filter.createdFrom),to=boundary(filter.createdTo,true),nextFrom=boundary(filter.nextFollowUpFrom),nextTo=boundary(filter.nextFollowUpTo,true);
 if((from!==undefined&&to!==undefined&&from>to)||(nextFrom!==undefined&&nextTo!==undefined&&nextFrom>nextTo))throw Error('Invalid CRM date range');
 const tags=Array.isArray(filter.tag)?filter.tag:filter.tag?[filter.tag]:[];
 const companies=new Map(data.companies.map(c=>[c.id,c])),members=new Map((data.members??[]).map(m=>[m.id,m]));
 const inRange=(value:string|undefined,start:number|undefined,end:number|undefined)=>start===undefined&&end===undefined||!!value&&Number.isFinite(Date.parse(value))&&(start===undefined||Date.parse(value)>=start)&&(end===undefined||Date.parse(value)<=end);
 return data.leads.map(lead=>{const company=companies.get(lead.companyId),contacts=data.contacts.filter(c=>lead.contactIds.includes(c.id)&&!c.archivedAt),followup=data.followups.filter(f=>f.leadId===lead.id&&f.kind==='followup'&&!f.archivedAt).sort((a,b)=>b.time.localeCompare(a.time)||b.createdAt.localeCompare(a.createdAt)||b.id.localeCompare(a.id))[0];const owner=Object.hasOwn(lead,'ownerMemberId')?(lead.ownerMemberId===null?'':members.get(lead.ownerMemberId!)?.name??lead.owner):(lead.owner||company?.owner||'');const isDue=!lead.archivedAt&&!company?.archivedAt&&!['won','lost'].includes(lead.stage)&&!!followup?.nextFollowUpAt&&Date.parse(followup.nextFollowUpAt)<=now;return {lead,company,contacts,followup,owner,isDue};}).filter(r=>(filter.archived||filter.includeArchived||!r.lead.archivedAt)&&(!filter.query||JSON.stringify([r.lead,r.company,r.contacts,r.owner]).toLowerCase().includes(filter.query.toLowerCase()))&&(!filter.country||r.company?.country===filter.country)&&(!filter.owner||r.owner===filter.owner)&&(!Object.hasOwn(filter,'ownerMemberId')||r.lead.ownerMemberId===filter.ownerMemberId)&&(!filter.source||r.lead.source===filter.source)&&(!filter.stage||r.lead.stage===filter.stage)&&(!(filter.due||filter.overdue)||r.isDue)&&tags.every(t=>[...(r.company?.tags??[]),...r.lead.tags].includes(t))&&(!filter.verificationStatus||r.contacts.some(c=>c.verificationStatus===filter.verificationStatus))&&inRange(r.lead.createdAt,from,to)&&inRange(r.followup?.nextFollowUpAt??undefined,nextFrom,nextTo)).sort((a,b)=>b.lead.createdAt.localeCompare(a.lead.createdAt)||a.lead.id.localeCompare(b.lead.id));
}
